export function getPlayerAvatar(idOrName: string): string {
  if (!idOrName) return 'https://ui-avatars.com/api/?name=Player&background=0284c7&color=ffffff&bold=true&size=256';
  if (PLAYER_AVATARS[idOrName]) return PLAYER_AVATARS[idOrName];

  const lower = idOrName.toLowerCase();
  for (const [key, url] of Object.entries(PLAYER_AVATARS)) {
    if (lower.includes(key.toLowerCase()) || key.toLowerCase().includes(lower)) {
      return url;
    }
  }

  // Fallbacks
  if (lower.includes('haye')) return PLAYER_AVATARS['haye-33'];
  if (lower.includes('klok')) return PLAYER_AVATARS['klok-23'];
  if (lower.includes('beckham')) return PLAYER_AVATARS['beckham-7'];
  if (lower.includes('peralta')) return PLAYER_AVATARS['peralta-10'];
  if (lower.includes('uilliam')) return PLAYER_AVATARS['uilliam-94'];
  if (lower.includes('menalo')) return PLAYER_AVATARS['menalo-9'];
  if (lower.includes('berguinho')) return PLAYER_AVATARS['berguinho-97'];
  if (lower.includes('sekulic')) return PLAYER_AVATARS['sekulic-99'];
  if (lower.includes('ragnar') || lower.includes('oratmangoen')) return PLAYER_AVATARS['ragnar-77'];
  if (lower.includes('reijnders') || lower.includes('eliano')) return PLAYER_AVATARS['reijnders-2'];
  if (lower.includes('walsh') || lower.includes('sandy')) return PLAYER_AVATARS['walsh-6'];
  if (lower.includes('mutombo') || lower.includes('gabriel')) return PLAYER_AVATARS['mutombo-3'];
  if (lower.includes('julio') || lower.includes('cesar')) return PLAYER_AVATARS['julio-cesar-4'];
  if (lower.includes('kakang')) return PLAYER_AVATARS['kakang-5'];
  if (lower.includes('loncar')) return PLAYER_AVATARS['loncar-22'];
  if (lower.includes('markx') || lower.includes('dion')) return PLAYER_AVATARS['markx-44'];
  if (lower.includes('matricardi')) return PLAYER_AVATARS['matricardi-48'];
  if (lower.includes('guaycochea') || lower.includes('luciano')) return PLAYER_AVATARS['guaycochea-8'];
  if (lower.includes('dedi') || lower.includes('kusnandar')) return PLAYER_AVATARS['dedi-11'];
  if (lower.includes('febri') || lower.includes('hariyadi')) return PLAYER_AVATARS['febri-13'];
  if (lower.includes('notsuda') || lower.includes('gakuto')) return PLAYER_AVATARS['notsuda-17'];
  if (lower.includes('adam') || lower.includes('alis')) return PLAYER_AVATARS['adam-18'];
  if (lower.includes('nazriel') || lower.includes('alfaro')) return PLAYER_AVATARS['nazriel-19'];
  if (lower.includes('teja') || lower.includes('alam')) return PLAYER_AVATARS['teja-14'];
  if (lower.includes('rakha') || lower.includes('rhaka')) return PLAYER_AVATARS['rakha-60'];
  if (lower.includes('fitrah')) return PLAYER_AVATARS['fitrah-81'];
  if (lower.includes('saddil') || lower.includes('ramdani')) return PLAYER_AVATARS['saddil-67'];
  if (lower.includes('ikwan') || lower.includes('tanamal')) return PLAYER_AVATARS['ikwan-40'];
  if (lower.includes('kevin') || lower.includes('pasha')) return PLAYER_AVATARS['kevin-pasha-66'];
  if (lower.includes('athaya') || lower.includes('zahran')) return PLAYER_AVATARS['athaya-36'];
  if (lower.includes('rafi') || lower.includes('rasyiq')) return PLAYER_AVATARS['rafi-30'];

  // Competitor Key Players
  if (lower.includes('ciro')) return PLAYER_AVATARS['ciro-77'];
  if (lower.includes('gustavo')) return PLAYER_AVATARS['gustavo-70'];
  if (lower.includes('yance')) return PLAYER_AVATARS['yance-23'];
  if (lower.includes('yakob')) return PLAYER_AVATARS['yakob-11'];
  if (lower.includes('mamut')) return PLAYER_AVATARS['mamut-9'];
  if (lower.includes('ridho')) return PLAYER_AVATARS['ridho-5'];
  if (lower.includes('witan')) return PLAYER_AVATARS['witan-78'];
  if (lower.includes('gajos')) return PLAYER_AVATARS['gajos-10'];
  if (lower.includes('kambuaya')) return PLAYER_AVATARS['kambuaya-19'];
  if (lower.includes('marukawa')) return PLAYER_AVATARS['marukawa-10'];
  if (lower.includes('lilipaly')) return PLAYER_AVATARS['lilipaly-14'];
  if (lower.includes('nadeo')) return PLAYER_AVATARS['nadeo-25'];
  if (lower.includes('moreira')) return PLAYER_AVATARS['moreira-10'];
  if (lower.includes('yance')) return PLAYER_AVATARS['yance-23'];
  if (lower.includes('yakob')) return PLAYER_AVATARS['yakob-2'];
  if (lower.includes('alex martins') || lower.includes('martins')) return PLAYER_AVATARS['alex-martins-9'];

  return `https://ui-avatars.com/api/?name=${encodeURIComponent(idOrName)}&background=0284c7&color=ffffff&bold=true&size=256`;
}

// Ensure 100% of players in OFFICIAL_SQUAD_2026_2027 have verified avatarUrl populated
OFFICIAL_SQUAD_2026_2027.forEach((p) => {
  if (!p.avatarUrl) {
    p.avatarUrl = PLAYER_AVATARS[p.id] || getPlayerAvatar(p.name);
  }
});

